    var MAST_RO_KEY = storyName + "-v1-mast-ro";
    var MAST_WATCH_KEY = storyName + "-v1-mast-watch";
    var PKG_TOGGLE_LOCK = storyName + "-v1-pkg-lock";
    var MAST_TOGGLE_T1 = storyName + "-v1-mast-toggle-t1";
