            if (groups[spec.id] && groups[spec.id].length) {
                list.push({
                    id: spec.id,
                    title: spec.title,
                    body: spec.body,
                    linkText: spec.linkText || "",
                    nextStep: spec.nextStep || "",
                    nodes: groups[spec.id]
                });
            }
