        var top = host.querySelector("[data-cscro-2455-expanded-top='1']");
        if (!top) {
            top = document.createElement("div");
            top.setAttribute("data-cscro-2455-expanded-top", "1");
            if (host.firstChild) host.insertBefore(top, host.firstChild);
            else host.appendChild(top);
        }
        var left = top.querySelector("[data-cscro-2455-expanded-left='1']");
        if (!left) {
            left = document.createElement("div");
            left.setAttribute("data-cscro-2455-expanded-left", "1");
            top.insertBefore(left, top.firstChild);
        }

        var heading =
            panel.querySelector("[data-cscro-2455-plan-heading]") ||
            panel.querySelector(".cscro-2455-plan-heading");
        if (heading && heading.parentNode !== left) {
            if (left.firstChild) left.insertBefore(heading, left.firstChild);
            else left.appendChild(heading);
        }

        var features = panel.querySelectorAll("[data-cscro-2455-feature='1']");
        var i;
        for (i = 0; i < features.length; i += 1) {
            if (features[i].parentNode !== left) left.appendChild(features[i]);
        }

