(() => {
    const runCookieConsentDetection = () => {
        try {
            const debug = false;
            const utils = window["optimizely"].get("utils");

            // Recursively check for cookie
            const waitForCookie = (cookieName, timeout, interval) => {
                return new Promise((resolve, reject) => {
                    const startTime = Date.now();

                    function checkCookie() {
                        const cookies = document.cookie.split(";");
                        for (const cookie of cookies) {
                            const [name, value] = cookie.trim().split("=");
                            if (name === cookieName) {
                                resolve(value);
                                return;
                            }
                        }
                        if (Date.now() - startTime >= timeout) {
                            reject(new Error(`Timeout waiting for cookie '${cookieName}'`));
                        } else {
                            setTimeout(checkCookie, interval);
                        }
                    }

                    checkCookie();
                });
            };

            // Activate Optimizely
            const activateOptimizely = () => {
                // Wait for OptanonAlertBoxClosed to exist
                waitForCookie("consentGroup", 2000, 50)
                    .then(() => {
                        // ensures the optimizely object is defined globally
                        if (!debug) {
                            window["optimizely"] = window["optimizely"] || [];

                            // sends the activate push to the Optimizely snippet
                            window["optimizely"].push({
                                type: "activate",
                            });
                        }
                        if (debug) console.log("OPTIMIZELY ACTIVATED");
                    })
                    .catch((error) => {
                        console.error(error.message);
                    });
            };

            //--------------------------------NEW COOKIE CONSENT LOGIC------------------------------

            // Accept all cookies CTA
            utils
                .waitForElement(
                    "#gcookiegprompt .cm-overlay-bottom-button-container #pref_optin"
                )
                .then((acceptAllCookiesCTA) => {
                    acceptAllCookiesCTA.addEventListener("click", activateOptimizely, {
                        once: true,
                    });
                });

            // Accept essential cookies CTA
            utils
                .waitForElement(
                    "#gcookiegprompt .cm-overlay-bottom-button-container #privacy_pref_optout"
                )
                .then((acceptEssentialCookiesCTA) => {
                    acceptEssentialCookiesCTA.addEventListener(
                        "click",
                        activateOptimizely,
                        { once: true }
                    );
                });

            // Click on Open Cookie Jar CTA
            utils
                .waitForElement(
                    "#gcookiegprompt .cm-overlay-bottom-button-container #open_preferences"
                )
                .then((openCookieJarCTA) => {
                    openCookieJarCTA.addEventListener("click", () => {
                        // Accept all cookies CTA
                        utils
                            .waitForElement(
                                "#gcookiePreferencesBanner .cm-overlay-inner-middle-container-content #gacceptAll"
                            )
                            .then((acceptAllCookiesCTA) => {
                                acceptAllCookiesCTA.addEventListener(
                                    "click",
                                    activateOptimizely,
                                    { once: true }
                                );
                            });

                        // Accept essential cookies CTA
                        utils
                            .waitForElement(
                                "#gcookiePreferencesBanner .cm-overlay-inner-middle-container-content #rejectAllBanner"
                            )
                            .then((acceptEssentialCookiesCTA) => {
                                acceptEssentialCookiesCTA.addEventListener(
                                    "click",
                                    activateOptimizely,
                                    { once: true }
                                );
                            });

                        // Save cookie setting CTA
                        utils
                            .waitForElement(
                                "#gcookiePreferencesBanner .cm-overlay-inner-middle-container-content #preferences_gprompt_submit"
                            )
                            .then((saveCookieSettingsCTA) => {
                                saveCookieSettingsCTA.addEventListener(
                                    "click",
                                    activateOptimizely,
                                    { once: true }
                                );
                            });
                    });
                });
        } catch (error) {
            console.log(error);
        }
    };
    window["optimizely"] = window["optimizely"] || [];
    window["optimizely"].push({
        type: "addListener",
        filter: {
            type: "lifecycle",
            name: "initialized",
        },
        handler: function (event) {
            runCookieConsentDetection();
        },
    });
})();
